<script lang="ts">let {data,form}=$props();let tab=$state('questions');</script>
<main class="mx-auto min-h-screen max-w-7xl p-6"><header class="mb-6 flex items-center justify-between"><div><a href="/" class="text-xl font-black text-navy">OWKR Exam</a><span class="ml-3 badge">관리자</span></div><a class="btn-secondary text-sm" href="/">메인으로</a></header><nav class="mb-5 flex gap-2 border-b border-line"><button class="px-4 py-3 font-semibold" class:border-b-2={tab==='questions'} onclick={()=>tab='questions'}>시험 문제 관리</button><button class="px-4 py-3 font-semibold" class:border-b-2={tab==='codes'} onclick={()=>tab='codes'}>응시 코드 관리</button><button class="px-4 py-3 font-semibold" class:border-b-2={tab==='results'} onclick={()=>tab='results'}>응시 결과</button></nav>{#if form?.message}<p class="mb-4 text-red-600">{form.message}</p>{:else if form?.success}<p class="mb-4 text-green-700">{form.success}</p>{/if}{#if tab==='questions'}<div class="grid gap-5 lg:grid-cols-[400px_1fr]"><form method="POST" action="?/question" class="card p-5"><h1 class="text-lg font-bold">문제 추가</h1><label class="label mt-4">유형</label><select name="type"><option value="multiple">객관식</option><option value="short">단답형</option><option value="essay">서술형</option></select><label class="label mt-3">문제 내용</label><textarea name="content" required class="w-full"></textarea><label class="label mt-3">보기 (객관식: 줄바꿈으로 구분)</label><textarea name="options" class="w-full"></textarea><label class="label mt-3">정답 번호 (0부터 시작)</label><input name="correct" type="number" value="0"/><label class="label mt-3">배점</label><input name="points" type="number" min="0" value="1"/><button class="btn mt-4 w-full">등록</button></form><section class="card overflow-hidden"><table class="w-full text-left text-sm"><thead class="bg-slate-50 text-slate-500"><tr><th class="p-3">순서</th><th>문제</th><th>유형</th><th>배점</th><th></th></tr></thead><tbody>{#each data.questions as q}<tr class="border-t border-line"><td class="p-3">{q.sortOrder}</td><td>{q.content}</td><td>{q.type==='multiple'?'객관식':q.type==='short'?'단답형':'서술형'}</td><td>{q.points}</td><td><form method="POST" action="?/deleteQuestion"><input type="hidden" name="id" value={q.id}/><button class="text-red-600">삭제</button></form></td></tr>{/each}</tbody></table></section></div>{:else if tab==='codes'}<div class="grid gap-5 lg:grid-cols-[350px_1fr]"><form method="POST" action="?/code" class="card p-5"><h1 class="text-lg font-bold">응시 코드 생성</h1><label class="label mt-4">연결할 Discord User ID</label><input class="w-full" name="discordId" placeholder="123456789012345678" required/><button class="btn mt-4 w-full">코드 생성</button></form><section class="card overflow-hidden"><table class="w-full text-left text-sm"><thead class="bg-slate-50 text-slate-500"><tr><th class="p-3">코드</th><th>Discord ID</th><th>상태</th><th>생성</th><th></th></tr></thead><tbody>{#each data.codes as c}<tr class="border-t border-line"><td class="p-3 font-mono font-bold">{c.code}</td><td>{c.discordId}</td><td>{c.status}</td><td>{c.createdAt.toLocaleString('ko-KR')}</td><td>{#if c.status==='unused'}<form method="POST" action="?/expireCode"><input name="id" type="hidden" value={c.id}/><button class="text-red-600">폐기</button></form>{/if}</td></tr>{/each}</tbody></table></section></div>{:else}<section class="card overflow-hidden"><table class="w-full text-left text-sm"><thead class="bg-slate-50 text-slate-500"><tr><th class="p-3">지원자</th><th>Discord ID</th><th>상태</th><th>객관식</th><th>주관식</th><th>총점</th><th>응시 시간</th></tr></thead><tbody>{#each data.attempts as a}<tr class="border-t border-line"><td class="p-3">{a.displayName}</td><td>{a.discordId}</td><td>{!a.submittedAt?'응시 중':a.totalScore===null?'채점 필요':a.timedOut?'시간 초과':'채점 완료'}</td><td>{a.objectiveScore}</td><td>{a.subjectiveScore??'-'}</td><td>{a.totalScore??'-'}</td><td>{a.submittedAt?Math.round((a.submittedAt.getTime()-a.startedAt.getTime())/60000)+'분':'-'}</td></tr>{/each}</tbody></table></section>{/if}</main>
